// Cracked Clay - color. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// The relief already carves the cracks and the AO darkens them; here every plate
// gets its own tone of clay, the damp crack walls sink toward u_col2, and fine
// hairline cracks (paint only) split the big plates.
// In scope: pModel, n_model, viewDir_model, mainLight_model.
// Dock colors: u_col1 = dry clay surface, u_col2 = damp depth of the cracks.

float DENSITY = 7.0 * max(E, 0.05);   // slider E   // MUST match the displacement
float CRACK   = 0.06;
float JITTER  = 0.85;
float HAIRLINE = 0.55;  // strength of the painted hairline cracks   [0 .. 1]
float TONE     = 0.12;  // tone variation between plates             [0 .. 0.3]

// --- SAME Voronoi as the displacement, plus the id of the nearest plate.
vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);
float d1 = 8.0;
float d2 = 8.0;
vec3 cell1 = vec3(0.0);
for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
    h3 += dot(h3, h3.yxz + 33.33);
    vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
    vec3 r = g + o - vf;
    float dd = dot(r, r);
    if (dd < d1) { d2 = d1; d1 = dd; cell1 = vi + g; }
    else if (dd < d2) { d2 = dd; }
}
float edge = 0.5 * (sqrt(d2) - sqrt(d1));

// per-plate tone (one random per plate)
vec3 hp = fract(cell1 * vec3(0.1031, 0.1030, 0.0973) + 0.71);
hp += dot(hp, hp.yxz + 33.33);
float plateTone = fract((hp.x + hp.y) * hp.z);

// --- hairline cracks: a finer Voronoi, painted only (no relief).
vec3 hq = pModel * DENSITY * 2.7;
vec3 hi = floor(hq);
vec3 hf = fract(hq);
float e1 = 8.0;
float e2 = 8.0;
for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 h3 = fract((hi + g) * vec3(0.1031, 0.1030, 0.0973) + 0.37);
    h3 += dot(h3, h3.yxz + 33.33);
    vec3 r = g + fract((h3.xxy + h3.yxx) * h3.zyx) - hf;
    float dd = dot(r, r);
    if (dd < e1) { e2 = e1; e1 = dd; }
    else if (dd < e2) { e2 = dd; }
}
float hair = 1.0 - smoothstep(0.0, 0.035, 0.5 * (sqrt(e2) - sqrt(e1)));
// a hairline fades out toward the middle of the plate: cracks start at the edges
hair *= 1.0 - smoothstep(0.15, 0.45, edge);

// --- fine grain of dried mud
vec3 gp = floor(pModel * 140.0);
float grain = fract(sin(dot(gp, vec3(12.99, 78.23, 37.71))) * 43758.5453) - 0.5;

// --- composition
vec3 clay = ubuf.u_col1 * (1.0 - TONE + 2.0 * TONE * plateTone) * (1.0 + 0.08 * grain);
// the plate edges, curled up, dry lighter; the crack walls stay damp and dark
clay *= 1.0 + 0.10 * (1.0 - smoothstep(0.0, 0.25, edge));
float inCrack = 1.0 - smoothstep(CRACK * 0.6, CRACK * 1.15, edge);
clay = mix(clay, ubuf.u_col2, inCrack * 0.85);
clay = mix(clay, ubuf.u_col2, hair * HAIRLINE * (1.0 - inCrack));

textureCol = clay;

