// Cracked Clay - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Dried mud: plates separated by deep cracks, their edges curling up a little.
// The plates are the cells of a 3D Voronoi; the cracks are the cell borders,
// DRILLED into the surface with a CSG difference (as in Porous Deep), so the
// walls are vertical and the engine's AO darkens the bottom for free.
// In scope: d_surf, p, pModel.
//
// SPEED. The 27-cell Voronoi only matters near the surface: farther outside than
// REACH the difference returns d_surf unchanged (a crack is at most CRACK wide and
// the curl is faded out before REACH), so skipping it there gives EXACTLY the same
// field. Rays that miss the object -- ~100 steps each -- pay one comparison.
// The cell randoms come from an arithmetic hash (no sin()), 1.6x faster in map().

float DENSITY = 7.0 * max(E, 0.05);   // slider E   // plates per unit        [3 .. 14]
float DEPTH   = 0.10 * max(F, 0.0);   // slider F   // crack depth (field)    [0 .. 0.2]
float CRACK   = 0.06;   // crack half-width, in cell units                    [0.03 .. 0.12]
float CURL    = 0.012;  // how much the plate edges curl up (field units)     [0 .. 0.03]
float JITTER  = 0.85;   // 0 = regular grid of plates, 1 = fully random       [0.5 .. 1.0]

float REACH = CRACK / DENSITY + 3.0 * CURL + 0.02;

if (d_surf < REACH) {
    vec3 vp = pModel * DENSITY;
    vec3 vi = floor(vp);
    vec3 vf = fract(vp);

    // nearest and second-nearest cell points (squared distances)
    float d1 = 8.0;
    float d2 = 8.0;
    for (int gx = -1; gx <= 1; gx++)
    for (int gy = -1; gy <= 1; gy++)
    for (int gz = -1; gz <= 1; gz++) {
        vec3 g = vec3(float(gx), float(gy), float(gz));
        vec3 h3 = fract((vi + g) * vec3(0.1031, 0.1030, 0.0973));
        h3 += dot(h3, h3.yxz + 33.33);
        vec3 o = 0.5 + JITTER * (fract((h3.xxy + h3.yxx) * h3.zyx) - 0.5);
        vec3 r = g + o - vf;
        float dd = dot(r, r);
        if (dd < d1) { d2 = d1; d1 = dd; }
        else if (dd < d2) { d2 = dd; }
    }
    // distance from the plate border, in cell units (~0 on the border)
    float edge = 0.5 * (sqrt(d2) - sqrt(d1));

    // plates curl up toward their edges. The curl fades out before REACH, so the
    // field joins d_surf continuously where the block is skipped.
    float curlFade = 1.0 - smoothstep(0.5 * REACH, REACH, d_surf);
    float plate = d_surf - CURL * curlFade * (1.0 - smoothstep(0.0, 0.25, edge));

    // CRACK VOLUME = slab around the border (crackDist < 0, model units)
    //                INTERSECTED with the top layer of the plate (DEPTH deep).
    float crackDist = (edge - CRACK) / DENSITY;
    float crackVol  = max(crackDist, -(plate + DEPTH));

    // CSG difference: plate minus crack volume. max() of two valid fields stays a
    // valid field, so the walls can be vertical without slowing the rays down.
    d_surf = max(plate, -crackVol);
}
